SELECT DATE_TRUNC('MONTH', s.opened_date) AS opened_month, CASE WHEN s.sqft >= 14127 THEN 'high' WHEN s.sqft >= 7105 THEN 'mid' ELSE 'low' END AS sqft_bucket, COUNT(*) AS store_sale_count, MAX(ss.sale_date) AS latest_sale_date FROM store_sales ss JOIN stores s ON ss.store_id = s.id GROUP BY DATE_TRUNC('MONTH', s.opened_date), CASE WHEN s.sqft >= 14127 THEN 'high' WHEN s.sqft >= 7105 THEN 'mid' ELSE 'low' END HAVING store_sale_count >= 4 ORDER BY sqft_bucket;
